CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;
CREATE TABLE "Users" (
    id integer GENERATED BY DEFAULT AS IDENTITY,
    username text NOT NULL,
    password text NOT NULL,
    CONSTRAINT "PK_Users" PRIMARY KEY (id)
);

CREATE TABLE "Boards" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" text NOT NULL,
    "Userid" integer,
    CONSTRAINT "PK_Boards" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Boards_Users_Userid" FOREIGN KEY ("Userid") REFERENCES "Users" (id)
);

CREATE TABLE "Columns" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" text NOT NULL,
    "BoardId" integer,
    CONSTRAINT "PK_Columns" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Columns_Boards_BoardId" FOREIGN KEY ("BoardId") REFERENCES "Boards" ("Id")
);

CREATE TABLE "Notes" (
    id integer GENERATED BY DEFAULT AS IDENTITY,
    name text NOT NULL,
    content text,
    "isDone" boolean NOT NULL,
    date date NOT NULL,
    "ColumnId" integer NOT NULL,
    CONSTRAINT "PK_Notes" PRIMARY KEY (id),
    CONSTRAINT "FK_Notes_Columns_ColumnId" FOREIGN KEY ("ColumnId") REFERENCES "Columns" ("Id") ON DELETE CASCADE
);

CREATE INDEX "IX_Boards_Userid" ON "Boards" ("Userid");

CREATE INDEX "IX_Columns_BoardId" ON "Columns" ("BoardId");

CREATE INDEX "IX_Notes_ColumnId" ON "Notes" ("ColumnId");

