ALTER INDEX "IX_Boards_Userid" RENAME TO "IX_Boards_UserId";

UPDATE "Columns" SET "BoardId" = 0 WHERE "BoardId" IS NULL;
ALTER TABLE "Columns" ALTER COLUMN "BoardId" SET NOT NULL;
ALTER TABLE "Columns" ALTER COLUMN "BoardId" SET DEFAULT 0;

UPDATE "Boards" SET "UserId" = 0 WHERE "UserId" IS NULL;
ALTER TABLE "Boards" ALTER COLUMN "UserId" SET NOT NULL;
ALTER TABLE "Boards" ALTER COLUMN "UserId" SET DEFAULT 0;

ALTER TABLE "Boards" ADD CONSTRAINT "FK_Boards_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" (id) ON DELETE CASCADE;

ALTER TABLE "Columns" ADD CONSTRAINT "FK_Columns_Boards_BoardId" FOREIGN KEY ("BoardId") REFERENCES "Boards" ("Id") ON DELETE CASCADE;

